const form = document.querySelector('#booking-form');
const dateInput = document.querySelector('[data-testid="booking-date"]');
const list = document.querySelector('[data-testid="booking-list"]');
const emptyState = document.querySelector('#empty-state');
const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
const formError = document.querySelector('#form-error');
const count = document.querySelector('#booking-count');
const bookings = [];

function getToday() {
  const now = new Date();
  const offset = now.getTimezoneOffset();
  return new Date(now.getTime() - offset * 60000).toISOString().slice(0, 10);
}

function showMessage(element, text) {
  element.textContent = text;
  element.hidden = false;
}

function clearMessage(element) {
  element.textContent = '';
  element.hidden = true;
}

function formatBookingDate(date, time) {
  const parsed = new Date(`${date}T${time}`);
  return parsed.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' });
}

function renderBookings() {
  list.querySelectorAll('[data-testid="booking"]').forEach((item) => item.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = String(bookings.filter((booking) => booking.status === 'active').length);

  bookings.forEach((booking) => {
    const article = document.createElement('article');
    article.className = `booking${booking.status === 'cancelled' ? ' cancelled' : ''}`;
    article.dataset.testid = 'booking';
    article.dataset.status = booking.status;

    const details = document.createElement('div');
    details.className = 'booking-details';
    const name = document.createElement('h3');
    name.dataset.testid = 'booking-name-display';
    name.textContent = booking.name;
    const info = document.createElement('p');
    info.textContent = `${booking.type} · ${formatBookingDate(booking.date, booking.time)}`;
    const email = document.createElement('p');
    email.textContent = booking.email;
    details.append(name, info, email);

    if (booking.status === 'cancelled') {
      const status = document.createElement('span');
      status.className = 'status';
      status.textContent = 'Cancelled';
      details.append(status);
    } else {
      const cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.className = 'cancel-button';
      cancel.dataset.testid = 'booking-cancel';
      cancel.textContent = 'Cancel';
      cancel.addEventListener('click', () => cancelBooking(booking.id));
      article.append(details, cancel);
    }
    if (!article.contains(details)) article.append(details);
    list.append(article);
  });
}

function cancelBooking(id) {
  const booking = bookings.find((item) => item.id === id);
  if (booking) {
    booking.status = 'cancelled';
    renderBookings();
  }
}

function handleSubmit(event) {
  event.preventDefault();
  clearMessage(formError);
  clearMessage(confirmation);
  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }
  const data = new FormData(form);
  const date = data.get('date');
  if (date < getToday()) {
    showMessage(formError, 'Please choose today or a future date.');
    dateInput.focus();
    return;
  }
  bookings.push({ id: crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${bookings.length}`, name: data.get('name').trim(), email: data.get('email').trim(), date, time: data.get('time'), type: data.get('type'), status: 'active' });
  renderBookings();
  form.reset();
  dateInput.min = getToday();
  showMessage(confirmation, 'Your appointment was booked successfully.');
}

dateInput.min = getToday();
form.addEventListener('submit', handleSubmit);
renderBookings();

const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const empty = document.getElementById('empty-state');
const confirmation = document.getElementById('booking-confirmation');
const count = document.getElementById('booking-count');
const bookings = [];

function localDateString() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
}
function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'});
}
function updateCount() {
  const active = bookings.filter(item => !item.cancelled).length;
  count.textContent = `${active} ${active === 1 ? 'appointment' : 'appointments'}`;
}
function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
  empty.hidden = bookings.length > 0;
  bookings.forEach((item, index) => {
    const card = document.createElement('article');
    card.className = 'booking' + (item.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    card.innerHTML = `<div><div class="booking-type">${item.type}</div><p class="booking-name" data-testid="booking-name-display"></p><p class="booking-meta">${formatDate(item.date)} · ${item.time} · ${item.email}</p></div>`;
    card.querySelector('[data-testid="booking-name-display"]').textContent = item.name;
    const action = document.createElement('div');
    if (item.cancelled) { action.className = 'cancelled-label'; action.textContent = 'Cancelled'; }
    else { const button = document.createElement('button'); button.className='cancel'; button.type='button'; button.dataset.testid='booking-cancel'; button.textContent='Cancel'; button.addEventListener('click', () => { item.cancelled=true; render(); }); action.appendChild(button); }
    card.appendChild(action); list.appendChild(card);
  });
  updateCount();
}
dateInput.min = localDateString();
form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = new FormData(form);
  const date = data.get('date');
  if (date < localDateString()) { dateInput.setCustomValidity('Please choose today or a future date.'); dateInput.reportValidity(); dateInput.setCustomValidity(''); return; }
  bookings.push({name:data.get('name'), email:data.get('email'), date, time:data.get('time'), type:data.get('type'), cancelled:false});
  render();
  confirmation.textContent = `Appointment confirmed for ${data.get('name')} — ${formatDate(date)} at ${data.get('time')}.`;
  confirmation.hidden = false;
  form.reset(); dateInput.min = localDateString();
  window.setTimeout(() => { confirmation.hidden = true; }, 6000);
});

