HTML:
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="description" content="A simple, focused to-do list application.">
  <title>To-do List</title>
  <link rel="stylesheet" href="styles.css">
  <script src="script.js" defer></script>
</head>
<body>
  <main class="app-shell">
    <section class="todo-card" aria-labelledby="page-title">
      <header class="app-header">
        <div>
          <p class="eyebrow">YOUR DAY, ORGANIZED</p>
          <h1 id="page-title">To-do List</h1>
          <p class="subtitle">Small steps make big progress.</p>
        </div>
        <div class="header-mark" aria-hidden="true">✓</div>
      </header>

      <form class="add-form" id="task-form">
        <label class="sr-only" for="task-input">New task</label>
        <input id="task-input" data-testid="task-input" type="text" placeholder="What needs to be done?" autocomplete="off" maxlength="200">
        <button id="task-add" data-testid="task-add" type="submit">Add task <span aria-hidden="true">＋</span></button>
      </form>

      <div class="list-toolbar">
        <h2>Today</h2>
        <p class="count"><span data-testid="incomplete-count">0</span> <span id="count-label">tasks left</span></p>
      </div>

      <div id="task-list" data-testid="task-list" class="task-list" aria-live="polite" aria-label="Tasks"></div>
      <p id="empty-state" class="empty-state">Your list is clear.<br><span>Add a task to get started.</span></p>
    </section>
    <p class="page-note">Tasks stay in this browser tab and reset when you refresh.</p>
  </main>
</body>
</html>

