const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('[data-testid="task-input"]');
const taskList = document.querySelector('[data-testid="task-list"]');
const incompleteCount = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.querySelector('#count-label');
const emptyMessage = document.querySelector('#empty-message');
const formError = document.querySelector('#form-error');

let tasks = [];
let nextTaskId = 1;

function showError(message) {
  formError.textContent = message;
  formError.hidden = false;
}

function clearError() {
  formError.textContent = '';
  formError.hidden = true;
}

function createTask(text) {
  return { id: nextTaskId++, text, completed: false };
}

function updateCount() {
  const remaining = tasks.filter(task => !task.completed).length;
  incompleteCount.textContent = String(remaining);
  countLabel.textContent = remaining === 1 ? 'incomplete task' : 'incomplete tasks';
}

function createTaskElement(task) {
  const item = document.createElement('li');
  item.className = 'task-item';
  item.dataset.testid = 'task';
  item.dataset.completed = String(task.completed);

  const toggle = document.createElement('input');
  toggle.type = 'checkbox';
  toggle.className = 'task-toggle';
  toggle.dataset.testid = 'task-complete';
  toggle.checked = task.completed;
  toggle.id = `task-toggle-${task.id}`;
  toggle.setAttribute('aria-label', `Mark ${task.text} as complete`);
  toggle.addEventListener('change', () => toggleTask(task.id, toggle.checked));

  const label = document.createElement('label');
  label.className = 'task-text';
  label.dataset.testid = 'task-text';
  label.htmlFor = toggle.id;
  label.textContent = task.text;

  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'delete-button';
  deleteButton.dataset.testid = 'task-delete';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', `Delete ${task.text}`);
  deleteButton.addEventListener('click', () => deleteTask(task.id));

  item.append(toggle, label, deleteButton);
  if (task.completed) item.classList.add('completed');
  return item;
}

function renderTasks() {
  taskList.replaceChildren(...tasks.map(createTaskElement));
  emptyMessage.hidden = tasks.length > 0;
  updateCount();
}

function addTask() {
  const text = taskInput.value.trim();
  if (!text) {
    showError('Enter a task before adding it.');
    taskInput.focus();
    return;
  }
  tasks.push(createTask(text));
  taskInput.value = '';
  clearError();
  renderTasks();
  taskInput.focus();
}

function toggleTask(id, completed) {
  const task = tasks.find(item => item.id === id);
  if (!task) return;
  task.completed = completed;
  renderTasks();
}

function deleteTask(id) {
  tasks = tasks.filter(task => task.id !== id);
  renderTasks();
}

taskForm.addEventListener('submit', event => {
  event.preventDefault();
  addTask();
});

renderTasks();

