application.javascript:
const form = document.getElementById('task-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const emptyState = document.getElementById('empty-state');
const countElement = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.getElementById('count-label');

let tasks = [];

function updateSummary() {
  const remaining = tasks.filter(task => !task.completed).length;
  countElement.textContent = remaining;
  countLabel.textContent = remaining === 1 ? 'remaining' : 'remaining';
  emptyState.hidden = tasks.length > 0;
}

function render() {
  list.replaceChildren();
  tasks.forEach(task => {
    const item = document.createElement('div');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'complete-button';
    toggle.dataset.testid = 'task-complete';
    toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
    toggle.setAttribute('aria-pressed', String(task.completed));
    toggle.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete task: ${task.text}`);
    remove.textContent = '×';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(candidate => candidate.id !== task.id);
      render();
    });

    item.append(toggle, text, remove);
    list.appendChild(item);
  });
  updateSummary();
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();

application.css:
* { box-sizing: border-box; }

:root {
  --ink: #18243d;
  --muted: #66728b;
  --line: #e4e9f2;
  --purple: #6657e8;
  --purple-dark: #5143cc;
  --soft-purple: #f1efff;
  --surface: #ffffff;
}

body {
  margin: 0;
  min-width: 320px;
  color: var(--ink);
  background: #f6f8fc;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.page-shell {
  min-height: 100vh;
  padding: 48px 20px 64px;
  background: radial-gradient(circle at 10% 0%, #e9e7ff 0, transparent 31%), #f6f8fc;
}

.quiz-card {
  width: min(720px, 100%);
  margin: auto;
  padding: 42px;
  background: var(--surface);
  border: 1px solid rgba(228, 233, 242, .9);
  border-radius: 24px;
  box-shadow: 0 20px 60px rgba(35, 48, 88, .1);
}

.quiz-header { margin-bottom: 30px; }
.eyebrow {
  color: var(--purple);
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
h1 { margin: 10px 0 8px; font-size: clamp(2rem, 5vw, 2.8rem); letter-spacing: -.045em; }
.quiz-header p { margin: 0; color: var(--muted); font-size: .98rem; }

.question-card {
  min-width: 0;
  margin: 0 0 17px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 16px;
}
legend { width: 100%; padding: 0; font-size: 1.05rem; font-weight: 750; line-height: 1.45; }
.question-number {
  display: inline-grid;
  width: 30px;
  height: 30px;
  margin-right: 8px;
  place-items: center;
  color: var(--purple);
  background: var(--soft-purple);
  border-radius: 9px;
  font-size: .7rem;
  vertical-align: middle;
}
.options { display: grid; gap: 9px; margin-top: 17px; }
.option {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: #46516a;
  cursor: pointer;
  transition: border-color .18s, background .18s, color .18s;
}
.option:hover { border-color: #b8b1ff; background: #faf9ff; }
.option:has(input:checked) { border-color: var(--purple); background: var(--soft-purple); color: var(--ink); font-weight: 650; }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.custom-radio { width: 17px; height: 17px; border: 2px solid #bbc3d2; border-radius: 50%; position: relative; flex: 0 0 auto; }
.option:has(input:checked) .custom-radio { border-color: var(--purple); }
.option:has(input:checked) .custom-radio::after { content: ""; position: absolute; inset: 3px; background: var(--purple); border-radius: 50%; }

.actions { display: flex; align-items: center; gap: 18px; margin-top: 26px; }
button { border: 0; border-radius: 11px; padding: 14px 20px; color: white; background: var(--purple); font: inherit; font-weight: 750; cursor: pointer; box-shadow: 0 8px 18px rgba(102, 87, 232, .24); }
button:hover { background: var(--purple-dark); }
button span { margin-left: 10px; font-size: 1.2rem; }
.message { margin: 0; color: #c34d57; font-size: .88rem; }
.result { display: none; margin-top: 30px; padding: 22px; text-align: center; background: #f8f7ff; border-radius: 16px; }
.result.visible { display: block; }
.result-label { color: var(--muted); font-size: .8rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.score { margin: 4px 0 0; color: var(--purple); font-size: 3.5rem; font-weight: 850; line-height: 1.1; }
.result-caption { color: var(--muted); font-size: .88rem; }

@media (max-width: 560px) {
  .page-shell { padding: 22px 12px 40px; }
  .quiz-card { padding: 25px 18px; border-radius: 18px; }
  .question-card { padding: 17px; }
  .actions { align-items: flex-start; flex-direction: column; }
}

application.javascript:
const form = document.getElementById('quiz-form');
const message = document.getElementById('message');
const result = document.querySelector('.result');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');

const answers = {
  'question-1': 'mars',
  'question-2': 'pacific',
  'question-3': 'carbon-dioxide'
};

form.addEventListener('submit', (event) => {
  event.preventDefault();
  message.textContent = '';

  const formData = new FormData(form);
  const names = Object.keys(answers);
  const unanswered = names.some((name) => !formData.get(name));

  if (unanswered) {
    message.textContent = 'Please choose one answer for each question.';
    return;
  }

  const score = names.reduce((total, name) => {
    return total + (formData.get(name) === answers[name] ? 1 : 0);
  }, 0);

  scoreElement.textContent = String(score);
  scoreElement.dataset.score = String(score);
  result.classList.add('visible');
});

