      {
        "testId": "quiz-submit",
        "requirement": "Apply to the control used to submit the completed quiz."
      },
      {
        "testId": "quiz-score",
        "requirement": "Apply to the element displaying the final numeric score after submission."
      }
    ],
    "stateAttributes": [
      {
        "attribute": "data-score",
        "appliesTo": "quiz-score",
        "requirement": "Before the quiz is submitted, data-score must be absent or empty. After submission, the element with data-testid=\"quiz-score\" must expose the numeric result using data-score=\"0\", \"1\", \"2\" or \"3\". Refreshing the page must return data-score to the absent or empty state."
