application.javascript:
const form = document.getElementById('add-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const count = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.getElementById('count-label');
const emptyState = document.getElementById('empty-state');

let tasks = [];

function render() {
  list.replaceChildren();
  tasks.forEach(task => {
    const item = document.createElement('article');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'task-complete';
    checkbox.dataset.testid = 'task-complete';
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', `Mark ${task.text} as complete`);
    checkbox.addEventListener('change', () => {
      task.completed = checkbox.checked;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'task-delete';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete ${task.text}`);
    remove.innerHTML = '&times;';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(candidate => candidate.id !== task.id);
      render();
    });

    item.append(checkbox, text, remove);
    list.append(item);
  });

  const remaining = tasks.filter(task => !task.completed).length;
  count.textContent = remaining;
  countLabel.textContent = remaining === 1 ? 'task left' : 'tasks left';
  emptyState.hidden = tasks.length !== 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();

