    card.dataset.status = booking.cancelled ? 'cancelled' : 'active';
    const top = document.createElement('div');
    top.className = 'booking-top';
    const details = document.createElement('div');
    const name = document.createElement('h3');
    name.className = 'booking-name';
    name.dataset.testid = 'booking-name-display';
    name.textContent = booking.name;
    const meta = document.createElement('div');
    meta.className = 'booking-meta';
    const appointmentDate = new Date(`${booking.date}T${booking.time}`);
    meta.textContent = `${appointmentDate.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })} · ${appointmentDate.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })} · ${booking.email}`;
    details.append(name, meta);
    top.appendChild(details);
    const badge = document.createElement('span');
    badge.className = 'badge';
    badge.textContent = booking.type;
    top.appendChild(badge);
    card.appendChild(top);
    if (booking.cancelled) {
      const label = document.createElement('div');
      label.className = 'cancelled-label';
      label.textContent = 'Cancelled';
      card.appendChild(label);
    } else {
      const cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.className = 'cancel-button';
      cancel.dataset.testid = 'booking-cancel';
      cancel.textContent = 'Cancel appointment';
      cancel.addEventListener('click', () => { bookings[index].cancelled = true; render(); });
      card.appendChild(cancel);
    }
    list.appendChild(card);
  });
}

