          <p class="form-footnote">Fields marked <span>*</span> are required.</p>
        </form>
      </div>

      <div class="bookings-panel">
        <div class="list-heading">
          <div>
            <p class="section-kicker">Your schedule</p>
            <h2>Upcoming bookings</h2>
          </div>
          <span class="booking-count" id="booking-count">0</span>
        </div>
        <div id="booking-confirmation" data-testid="booking-confirmation" class="confirmation" role="status" aria-live="polite" hidden></div>
        <div id="booking-list" data-testid="booking-list" class="booking-list" aria-live="polite">
          <div class="empty-state" id="empty-state"><div class="empty-icon">◷</div><h3>Your schedule is clear</h3><p>Created appointments will appear here.</p></div>
        </div>
      </div>
    </section>
    <footer>Appointments are stored temporarily in page memory.</footer>
  </main>
</body>
</html>

