application.javascript:
document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('quiz-form');
  const status = document.getElementById('status');
  const scoreEl = document.querySelector('[data-testid="quiz-score"]');
  const result = document.querySelector('.result');
  const answers = { q1: 'b', q2: 'c', q3: 'b' };

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const selected = {};
    Object.keys(answers).forEach((name) => {
      const choice = form.querySelector(`input[name="${name}"]:checked`);
      selected[name] = choice ? choice.value : '';
    });
    const unanswered = Object.keys(answers).filter((name) => !selected[name]);
    if (unanswered.length) {
      status.textContent = `Please answer ${unanswered.length === 1 ? 'the remaining question' : 'all three questions'} first.`;
      return;
    }
    status.textContent = '';
    let score = 0;
    Object.keys(answers).forEach((question) => {
      if (selected[question] === answers[question]) score += 1;
    });
    scoreEl.textContent = String(score);
    scoreEl.dataset.score = String(score);
    result.classList.add('show');
  });
});

